use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sqlx::{FromRow, PgPool};
use uuid::Uuid;

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Chat {
    pub id: Uuid,
    pub user_id: Uuid,
    pub name: String,
    pub is_pinned: bool,
    pub created_at: Option<DateTime<Utc>>,
    #[sqlx(rename = "last_message")]
    pub last_message: Option<String>,
}

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Message {
    pub id: Uuid,
    pub chat_id: Uuid,
    pub role: String,
    pub content: String,
    pub image_url: Option<String>,
    pub created_at: Option<DateTime<Utc>>,
}

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Upload {
    pub id: Uuid,
    pub user_id: Uuid,
    pub filename: String,
    pub content: String,
    pub created_at: Option<DateTime<Utc>>,
}

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Formula {
    pub id: Uuid,
    pub grade: i32,
    pub name: String,
    pub equation: String,
    pub description: Option<String>,
}

pub async fn list_chats(pool: &PgPool, user_id: Uuid) -> anyhow::Result<Vec<Chat>> {
    let chats = sqlx::query_as!(
        Chat,
        r#"
        SELECT
            c.id as "id!",
            c.user_id as "user_id!",
            c.name as "name!",
            c.is_pinned as "is_pinned!",
            c.created_at,
            m.content as "last_message"
        FROM chats c
        LEFT JOIN LATERAL (
            SELECT content FROM messages
            WHERE chat_id = c.id
            ORDER BY created_at DESC
            LIMIT 1
        ) m ON true
        WHERE c.user_id = $1
        ORDER BY c.is_pinned DESC, c.created_at DESC
        "#,
        user_id
    )
    .fetch_all(pool)
    .await?;
    Ok(chats)
}

pub async fn list_uploads(pool: &PgPool, user_id: Uuid) -> anyhow::Result<Vec<Upload>> {
    let uploads = sqlx::query_as!(
        Upload,
        r#"SELECT id as "id!", user_id as "user_id!", filename as "filename!", content as "content!", created_at FROM uploads WHERE user_id = $1 ORDER BY created_at DESC"#,
        user_id
    )
    .fetch_all(pool)
    .await?;
    Ok(uploads)
}

pub async fn get_chat_history(pool: &PgPool, chat_id: Uuid) -> anyhow::Result<Vec<Message>> {
    let messages = sqlx::query_as!(
        Message,
        r#"SELECT id as "id!", chat_id as "chat_id!", role as "role!", content as "content!", image_url, created_at FROM messages WHERE chat_id = $1 ORDER BY created_at ASC"#,
        chat_id
    )
    .fetch_all(pool)
    .await?;
    Ok(messages)
}

pub async fn list_formulas(pool: &PgPool, grade: Option<i32>) -> anyhow::Result<Vec<Formula>> {
    let formulas = match grade {
        Some(g) => {
            sqlx::query_as!(
                Formula,
                r#"SELECT id, grade, name, equation, description FROM formulas WHERE grade = $1"#,
                g
            )
            .fetch_all(pool)
            .await?
        }
        None => {
            sqlx::query_as!(
                Formula,
                r#"SELECT id, grade, name, equation, description FROM formulas"#
            )
            .fetch_all(pool)
            .await?
        }
    };
    Ok(formulas)
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sqlx::{FromRow, PgPool};
use uuid::Uuid;

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Chat {
    pub id: Uuid,
    pub user_id: Uuid,
    pub name: String,
    pub is_pinned: bool,
    pub created_at: Option<DateTime<Utc>>,
    #[sqlx(rename = "last_message")]
    pub last_message: Option<String>,
}

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Message {
    pub id: Uuid,
    pub chat_id: Uuid,
    pub role: String,
    pub content: String,
    pub image_url: Option<String>,
    pub created_at: Option<DateTime<Utc>>,
}

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Upload {
    pub id: Uuid,
    pub user_id: Uuid,
    pub filename: String,
    pub content: String,
    pub created_at: Option<DateTime<Utc>>,
}

#[derive(Debug, Serialize, Deserialize, FromRow)]
pub struct Formula {
    pub id: Uuid,
    pub grade: i32,
    pub name: String,
    pub equation: String,
    pub description: Option<String>,
}

pub async fn list_chats(pool: &PgPool, user_id: Uuid) -> anyhow::Result<Vec<Chat>> {
    let chats = sqlx::query_as!(
        Chat,
        r#"
        SELECT
            c.id as "id!",
            c.user_id as "user_id!",
            c.name as "name!",
            c.is_pinned as "is_pinned!",
            c.created_at,
            (SELECT content FROM messages WHERE chat_id = c.id ORDER BY created_at DESC LIMIT 1) as "last_message"
        FROM chats c
        WHERE c.user_id = $1
        ORDER BY c.is_pinned DESC, c.created_at DESC
        "#,
        user_id
    )
    .fetch_all(pool)
    .await?;
    Ok(chats)
}

